package config

import (
	"errors"
	"net/http"

	"github.com/0xJacky/Nginx-UI/internal/site"
	"github.com/gin-gonic/gin"
	"github.com/spf13/cast"
	"github.com/uozi-tech/cosy"
)

// rejectManagedSiteFile refuses edits to the file of a site generated by an
// ingress unless the request passes ?force=1, the same rule the site API
// applies. It responds and reports true when the request must stop.
func rejectManagedSiteFile(c *gin.Context, absPath string) bool {
	err := site.CheckManagedPath(absPath, site.Force(cast.ToBool(c.Query("force"))))
	if err == nil {
		return false
	}
	var cErr *cosy.Error
	if site.IsManagedByIngress(err) && errors.As(err, &cErr) {
		c.JSON(http.StatusConflict, cErr)
		return true
	}
	cosy.ErrHandler(c, err)
	return true
}
